mapper.select:
SELECT TC.COMPANY_ID, TC.COMPANY_NM, TC.USE_YN FROM TM_COMPANY TC WHERE 1 = 1
AND TC.COMPANY_ID = #{COMPANY_ID}
AND TC.COMPANY_NM LIKE '%' || #{COMPANY_NM} || '%'
AND TC.USE_YN = #{USE_YN}
ORDER BY TC.COMPANY_ID

SELECT A.LOGIN_ID, A.MEMBER_ID, D.LOGIN_GB, PKG_COMMON.FN_DECRYPT(D.REGIST_NO) AS REGIST_NO, A.ASSOCIATION_ID, A.COMPANY_ID, A.BRANCH_ID, E.COMPANY_NM || ' ' || B.BRANCH_NM AS BRANCH_NM, A.SANGSA_ID, C.SANGSA_NM, A.MEMBER_NM, A.MEMBER_GB, PKG_COMMON.FN_DECRYPT(A.TEL_NO) AS TEL_NO, PKG_COMMON.FN_DECRYPT(A.MPHONE_NO) AS MPHONE_NO, A.USE_YN, TO_CHAR(A.INS_DATE, 'YYYYMMDD') AS INS_DATE, TO_CHAR(A.CONFIRM_DT, 'YYYYMMDD') AS CONFIRM_DT FROM TM_MEMBER_DT A, TM_BRANCH B, TM_SANGSA C, TM_MEMBER_MT D, TM_COMPANY E WHERE A.COMPANY_ID = B.COMPANY_ID AND A.COMPANY_ID = E.COMPANY_ID AND A.ASSOCIATION_ID = E.ASSOCIATION_ID AND A.LOGIN_ID = D.LOGIN_ID AND A.BRANCH_ID = B.BRANCH_ID AND A.COMPANY_ID = C.COMPANY_ID(+) AND A.BRANCH_ID = C.BRANCH_ID(+) AND A.SANGSA_ID = C.SANGSA_ID(+)
AND A.COMPANY_ID = #{COMPANY_ID}
AND TO_CHAR(A.INS_DATE, 'YYYYMMDD') BETWEEN #{ST_DATE} AND #{ED_DATE}
AND A.BRANCH_ID = #{BRANCH_ID}
AND A.MEMBER_ID LIKE '%' || #{MEMBER_ID} || '%'
AND A.LOGIN_ID LIKE '%' || #{LOGIN_ID} || '%'
AND A.MEMBER_NM LIKE '%' || #{MEMBER_NM} || '%'
AND A.USE_YN = #{USE_YN}
AND A.MEMBER_GB LIKE '%' || #{MEMBER_GB}
ORDER BY A.COMPANY_ID, A.BRANCH_ID, A.SANGSA_ID, A.MEMBER_ID

mapper.delete:
DELETE FROM TM_WORK_MB
WHERE COMPANY_ID = #{COMPANY_ID}
  AND MEMBER_ID = #{MEMBER_ID}

mapper.update:
UPDATE TM_MEMBER_DT
SET PWD_CH_DT = SYSDATE
WHERE LOGIN_ID = #{LOGIN_ID}

mapper.select:
SELECT ND.DELIVERY_ID, ND.DELIVERY_NM, ND.COMPANY_ID, TC.COMPANY_NM, ND.TEL_NO, ND.USE_YN FROM TM_NUMPLATE_DELIVERY ND, TM_COMPANY TC WHERE ND.COMPANY_ID = TC.COMPANY_ID(+)
AND ND.COMPANY_ID = #{COMPANY_ID}
ORDER BY ND.DELIVERY_ID

SELECT COMPANY_ID, COMPANY_NM, BRANCH_ID, BRANCH_NM, BIZ_NO, POST_NO, PASS_WD, TEL_NO, PKG_COMMON.FN_DECRYPT(PHONE_NO) AS PHONE_NO, PKG_COMMON.FN_DECRYPT(ADDRESS) AS ADDRESS, PKG_COMMON.FN_DECRYPT(ADDRESS_DT) AS ADDRESS_DT, ETC1, ETC2, ETC3, ETC4, ETC5, COMPANY_ID || BRANCH_ID as CODE_ID, BRANCH_NM as CODE_NM, USE_YN FROM TM_CARNO_COMPANY WHERE USE_YN = 'Y'
AND COMPANY_ID = #{COMPANY_ID}
AND BRANCH_ID = #{BRANCH_ID}
AND (PKG_COMMON.FN_DECRYPT(ADDRESS) LIKE '%' || #{AREA} || '%' OR BRANCH_NM LIKE '%' || #{AREA} || '%')
ORDER BY COMPANY_ID, TO_NUMBER(BRANCH_ID)

SELECT COUNT(1)
FROM TM_SANGSA
WHERE COMPANY_ID = #{COMPANY_ID}
  AND BRANCH_ID = #{BRANCH_ID}
  AND UPPER(TRIM(SANGSA_NM)) = UPPER(TRIM(#{SANGSA_NM}))
  AND NVL(USE_YN, 'Y') = 'Y'

SELECT TO_CHAR(
           NVL(MAX(
               CASE
                   WHEN REGEXP_LIKE(TO_CHAR(SANGSA_ID), '^[0-9]+$')
                   THEN TO_NUMBER(SANGSA_ID)
                   ELSE 0
               END
           ), 0) + 1
       ) AS NEXT_SANGSA_ID
FROM TM_SANGSA
WHERE COMPANY_ID = #{COMPANY_ID}
  AND BRANCH_ID = #{BRANCH_ID}
